@push('scripts')<script>$(function(){var t=$('#item-categories-table'),x=$.fn.dataTable.render.text(),s=$('#category-status-filter');var dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.is_active=s.val();}},buttons:[window.erpExcelButton(t)],order:[[0,'asc']],columns:[{data:'code',render:x.display},{data:'name',render:x.display},{data:'status_label',render:x.display},{data:null,orderable:false,searchable:false,className:'text-end',render:function(v,z,r){if(z!=='display')return '';var h=r.edit_url?'<a class="btn btn-sm btn-outline-dark" href="'+x.display(r.edit_url)+'"><i class="bx bx-edit me-1" aria-hidden="true"></i>แก้ไข</a> ':'';return h+(r.delete_url?'<button class="btn btn-sm btn-outline-danger js-master-delete" data-url="'+x.display(r.delete_url)+'" title="ลบ"><i class="bx bx-trash" aria-hidden="true"></i></button>':'');}}]}));s.on('change',function(){dt.ajax.reload();});$('#category-filter-reset').on('click',function(){s.val('1').trigger('change');});$(document).on('click','.js-master-delete',function(){var b=$(this);Swal.fire({icon:'warning',text:'ยืนยันการลบข้อมูลที่ยังไม่ถูกใช้งาน?',showCancelButton:true,confirmButtonText:'ลบ',cancelButtonText:'ยกเลิก'}).then(function(r){if(!r.isConfirmed)return;$.ajax({url:b.data('url'),method:'DELETE',data:{_token:$('meta[name=csrf-token]').attr('content')}}).done(function(r){Swal.fire({icon:'success',text:r.msg,timer:1000,showConfirmButton:false});dt.ajax.reload(null,false)}).fail(function(x){Swal.fire({icon:'error',text:x.responseJSON?.msg||x.responseJSON?.message||'ลบไม่สำเร็จ'})});});});});</script>@endpush
